import sys
import argparse
import json
import xml.etree.ElementTree as ET
from html.parser import HTMLParser
import os

def print_help():
    print("""Command-line XML and HTML beautifier and content extractor

Usage:
  xq [flags]

Flags:
  -a, --attr string      Extract an attribute value instead of node content for provided CSS query
  -c, --color            Force colorful output
      --compact          Compact JSON output (no indentation)
  -d, --depth int        Maximum nesting depth for JSON output (-1 for unlimited) (default -1)
  -e, --extract string   Extract a single node from XML
  -h, --help             Print this help message
  -m, --html             Use HTML formatter
  -i, --in-place         Format file in place
      --indent int       Use the given number of spaces for indentation (default 2)
  -j, --json             Output the result as JSON
      --no-color         Disable colorful output
  -n, --node             Return the node content instead of text
  -q, --query string     Extract the node(s) using CSS selector
      --tab              Use tabs for indentation
  -v, --version          Print version information
  -x, --xpath string     Extract the node(s) from XML""")

class HTMLToET(HTMLParser):
    def __init__(self):
        super().__init__()
        self.root = ET.Element('root')
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        el = ET.SubElement(self.stack[-1], tag, dict(attrs))
        self.stack.append(el)

    def handle_endtag(self, tag):
        for i in range(len(self.stack)-1, 0, -1):
            if self.stack[i].tag == tag:
                self.stack = self.stack[:i]
                break

    def handle_data(self, data):
        if self.stack[-1].text:
            self.stack[-1].text += data
        else:
            self.stack[-1].text = data

    def handle_startendtag(self, tag, attrs):
        ET.SubElement(self.stack[-1], tag, dict(attrs))

def to_dict(element):
    res = {}
    for attr, value in element.attrib.items():
        res['@' + attr] = value

    for child in element:
        child_dict = to_dict(child)
        if child.tag in res:
            if not isinstance(res[child.tag], list):
                res[child.tag] = [res[child.tag]]
            res[child.tag].append(child_dict)
        else:
            res[child.tag] = child_dict

    text = element.text.strip() if element.text else ""
    if text:
        if res:
            res['#text'] = text
        else:
            return text
    elif not res:
        return {}

    # Sort keys
    return dict(sorted(res.items()))

def colorize_json(s):
    # Very simple JSON colorizer to match xq
    # Braces/Brackets: Yellow (\033[33m)
    # Keys: Light Blue (\033[94m)
    # Values: Green (\033[32m)
    lines = s.split('\n')
    new_lines = []
    for line in lines:
        # This is a very rough approximation
        new_line = ""
        i = 0
        while i < len(line):
            if line[i] in '{}[]:,':
                color = "\033[33m" if line[i] in '{}[]' else ""
                if color:
                    new_line += color + line[i] + "\033[0m"
                else:
                    new_line += line[i]
                i += 1
            elif line[i] == '"':
                start = i
                i += 1
                while i < len(line) and line[i] != '"':
                    if line[i] == '\\': i += 1
                    i += 1
                i += 1
                token = line[start:i]
                if i < len(line) and line[i] == ':':
                    new_line += "\033[94m" + token + "\033[0m"
                else:
                    new_line += "\033[32m" + token + "\033[0m"
            elif line[i:i+4] == 'true' or line[i:i+5] == 'false' or line[i:i+4] == 'null' or line[i].isdigit():
                start = i
                while i < len(line) and (line[i].isalnum() or line[i] in '.-'):
                    i += 1
                new_line += "\033[32m" + line[start:i] + "\033[0m"
            else:
                new_line += line[i]
                i += 1
        new_lines.append(new_line)
    return '\n'.join(new_lines)

def format_xml(element, level=0, indent="  "):
    # Custom XML formatter to match xq's behavior
    res = indent * level + "<" + element.tag
    for attr, value in element.attrib.items():
        res += ' ' + attr + '="' + value + '"'

    if len(element) == 0 and not element.text:
        res += "/>"
        return res

    res += ">"
    if element.text:
        res += element.text

    if len(element) > 0:
        res += "\n"
        for child in element:
            res += format_xml(child, level + 1, indent) + "\n"
        res += indent * level

    res += "</" + element.tag + ">"
    return res

