            self.stack[-1].text += data
        else:
            self.stack[-1].text = data

    def handle_startendtag(self, tag, attrs):
        ET.SubElement(self.stack[-1], tag, dict(attrs))

def get_all_text(element):
    text = element.text or ""
    for child in element:
        text += get_all_text(child)
        if child.tail:
            text += child.tail
    return text

def to_dict(element, depth=-1, current_depth=0):
    if depth != -1 and current_depth >= depth:
        return get_all_text(element).strip()

    res = {}
    for attr, value in element.attrib.items():
        res['@' + attr] = value

    for child in element:
        child_dict = to_dict(child, depth, current_depth + 1)
        if child.tag in res:
            if not isinstance(res[child.tag], list):
                res[child.tag] = [res[child.tag]]
            res[child.tag].append(child_dict)
        else:
            res[child.tag] = child_dict

    text = element.text.strip() if element.text else ""
    if text:
        if res:
            res['#text'] = text
        else:
            return text
    elif not res:
        return {}

    return dict(sorted(res.items()))

def colorize_json(s):
    lines = s.split('\n')
    new_lines = []
    for line in lines:
        new_line = ""
        i = 0
        while i < len(line):
            if line[i] in '{}[]:,':
                color = "\033[33m" if line[i] in '{}[]' else ""
                if color:
                    new_line += color + line[i] + "\033[0m"
                else:
                    new_line += line[i]
                i += 1
            elif line[i] == '"':
                start = i
                i += 1
                while i < len(line) and line[i] != '"':
                    if line[i] == '\\': i += 1
                    i += 1
                i += 1
                token = line[start:i]
                if i < len(line) and line[i] == ':':
                    new_line += "\033[94m" + token + "\033[0m"
                else:
                    new_line += "\033[32m" + token + "\033[0m"
            elif line[i:i+4] in ['true', 'null'] or line[i:i+5] == 'false' or line[i].isdigit() or (line[i] == '-' and i+1 < len(line) and line[i+1].isdigit()):
                start = i
                while i < len(line) and (line[i].isalnum() or line[i] in '.-'):
                    i += 1
                new_line += "\033[32m" + line[start:i] + "\033[0m"
            else:
                new_line += line[i]
                i += 1
        new_lines.append(new_line)
    return '\n'.join(new_lines)

def colorize_xml(s):
    # Tags/Brackets: Yellow (\033[33m)
    # Attribute names: Default
    # Attribute values (including =): Green (\033[32m)
    # Comments: Light Blue (\033[94m)
    # Text: Default

    res = ""
    i = 0
    while i < len(s):
        if s[i:i+4] == "<!--":
            start = i
            i = s.find("-->", i)
            if i == -1: i = len(s)
            else: i += 3
            res += "\033[94m" + s[start:i] + "\033[0m"
        elif s[i] == '<':
            start = i
            i += 1
            if i < len(s) and s[i] == '/': i += 1
            while i < len(s) and (s[i].isalnum() or s[i] in ':_-'): i += 1
            res += "\033[33m" + s[start:i] + "\033[0m"

            while i < len(s) and s[i] != '>' and s[i:i+2] != '/>':
                if s[i].isspace():
                    res += s[i]
                    i += 1
                elif s[i:i+2] == '="':
                    start = i
                    i += 2
                    while i < len(s) and s[i] != '"':
                        if s[i] == '\\': i += 1
                        i += 1
                    if i < len(s): i += 1
                    res += "\033[32m" + s[start:i] + "\033[0m"
                else:
                    res += s[i]
                    i += 1

            if i < len(s) and s[i:i+2] == '/>':
                res += "\033[33m/>\033[0m"
                i += 2
            elif i < len(s) and s[i] == '>':
                res += "\033[33m>\033[0m"
                i += 1
        else:
            res += s[i]
            i += 1
    return res

def format_node(element, level=0, indent="  ", is_html=False):
    line = indent * level + "<" + element.tag
    for attr, value in element.attrib.items():
