                        i += 1
                    if i < len(s): i += 1
                    res += "\033[32m" + s[start_attr:i] + "\033[0m"
                else: res += s[i]; i += 1
            if i+1 < len(s) and s[i:i+2] == '/>': res += "\033[33m/>\033[0m"; i += 2
            elif i < len(s) and s[i] == '>': res += "\033[33m>\033[0m"; i += 1
            continue
        res += s[i]; i += 1
    return res

def format_node(element, level=0, indent="  ", is_html=False):
    line = indent * level + "<" + element.tag
    attrs = sorted(element.attrib.items())
    for attr, value in attrs: line += ' ' + attr + '="' + value + '"'
    if len(element) == 0 and not element.text:
        if is_html and element.tag.lower() in ['div', 'p', 'span', 'script', 'title', 'html', 'body', 'head']: line += "></" + element.tag + ">"
        else: line += "/>"
        return line
    line += ">"
    if element.text: line += element.text
    if len(element) > 0:
        line += "\n"
        for child in element: line += format_node(child, level + 1, indent, is_html) + "\n"
        line += indent * level
    line += "</" + element.tag + ">"
    return line

def css_to_xpath(query):
    xpath = ".//" + query.replace(" > ", "/").replace(" ", "//")
    xpath = re.sub(r'\.([a-zA-Z0-9_-]+)', r"[contains(@class, '\1')]", xpath)
    xpath = re.sub(r'#([a-zA-Z0-9_-]+)', r"[@id='\1']", xpath)
    return xpath

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("-a", "--attr"); parser.add_argument("-c", "--color", action="store_true")
    parser.add_argument("--compact", action="store_true"); parser.add_argument("-d", "--depth", type=int, default=-1)
    parser.add_argument("-e", "--extract"); parser.add_argument("-h", "--help", action="store_true")
    parser.add_argument("-m", "--html", action="store_true"); parser.add_argument("-i", "--in-place", action="store_true")
    parser.add_argument("--indent", type=int, default=2); parser.add_argument("-j", "--json", action="store_true")
    parser.add_argument("--no-color", action="store_true"); parser.add_argument("-n", "--node", action="store_true")
    parser.add_argument("-q", "--query"); parser.add_argument("--tab", action="store_true")
    parser.add_argument("-v", "--version", action="store_true"); parser.add_argument("-x", "--xpath")
    parser.add_argument("files", nargs="*")
    args = parser.parse_args()
    if args.help: print_help(); return
    if args.version: print("xq version 1.4.0"); return
    if args.in_place and len(args.files) != 1:
        print("Error: in-place formatting requires a file path (and only one file path)", file=sys.stderr); sys.exit(1)
    if not args.files: process_data(sys.stdin.read(), args)
    else:
        if args.in_place:
            with open(args.files[0], 'r') as f: data = f.read()
            with open(args.files[0], 'w') as f: sys.stdout = f; process_data(data, args)
        else:
            for file in args.files:
                with open(file, 'r') as f: process_data(f.read(), args)

def process_data(data, args):
    if not data.strip(): return
    try:
        if data.strip().startswith('{') or data.strip().startswith('['):
            json_data = json.loads(data); output_json(json_data, args); return
    except: pass
    if args.html:
        parser = HTMLToET(); parser.feed(data); root = parser.root
        if len(root) == 1: root = root[0]
    else:
        try:
            temp_root = ET.fromstring("<r>" + data + "</r>")
            root = temp_root[0] if len(temp_root) == 1 else temp_root
        except:
            parser = HTMLToET(); parser.feed(data); root = parser.root
            if len(root) == 1: root = root[0]
    results = []
    if args.xpath or args.extract:
        xpath = args.xpath or args.extract; attr_to_get = None
        if '/@' in xpath: xpath, attr_to_get = xpath.split('/@')
        if xpath.startswith('//'): xpath = '.' + xpath
        elif xpath.startswith('/'): xpath = '.' + xpath
        found = root.findall(xpath)
        if args.extract and found: found = found[:1]
        for el in found:
            if attr_to_get: results.append(el.attrib.get(attr_to_get, ""))
            elif args.node: results.append(el)
            else: results.append(get_all_text(el).strip())
    elif args.query:
        found = root.findall(css_to_xpath(args.query))
        for el in found:
            if args.attr: results.append(el.attrib.get(args.attr, ""))
            elif args.node: results.append(el)
            else: results.append(get_all_text(el).strip())
    else: results = [root]
    indent_str = "\t" if args.tab else " " * args.indent
    do_color = args.color or (not args.no_color and sys.stdout.isatty())
    if args.json and not (args.xpath or args.query or args.extract):
        if root.tag == 'r' and not data.strip().startswith('<r>'):
            json_dict = {}
            for child in root:
                child_dict = to_dict(child, args.depth)
                if child.tag in json_dict:
                    if not isinstance(json_dict[child.tag], list): json_dict[child.tag] = [json_dict[child.tag]]
                    json_dict[child.tag].append(child_dict)
                else: json_dict[child.tag] = child_dict
            json_dict = dict(sorted(json_dict.items()))
        else: json_dict = {root.tag: to_dict(root, args.depth)}
        output_json(json_dict, args)
    else:
        for res in results:
            if isinstance(res, str): print(res)
            else:
                out = format_node(res, 0, indent_str, args.html)
                if do_color: out = colorize_xml(out)
                print(out)

def output_json(json_data, args):
    indent = None if args.compact else (args.indent if not args.tab else "\t")
    out = json.dumps(json_data, indent=indent, sort_keys=True, separators=(',', ': ') if not args.compact else (',', ':'))
    if not args.compact:
        out = re.sub(r'\{\n(\s*)\}', lambda m: '{\n\n' + m.group(1) + '}', out)
    if args.color or (not args.no_color and sys.stdout.isatty()): out = colorize_json(out)
    print(out)

if __name__ == "__main__": main()
